css:
.toggle-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  border-radius: 12px;
  padding: 0.25em;
  background: rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(12px);
  box-shadow: 0 0 20px rgba(0, 255, 255, 0.2);
  font-size: 1.5em; /* Demo size */
}

.toggle-checkbox {
  appearance: none;
  position: absolute;
  z-index: 1;
  border-radius: inherit;
  width: 100%;
  height: 100%;
  font: inherit;
  opacity: 0;
  cursor: pointer;
}

.toggle-container {
  display: flex;
  align-items: center;
  position: relative;
  border-radius: 10px;
  width: 3.5em;
  height: 1.8em;
  background: linear-gradient(
    45deg,
    rgba(0, 240, 255, 0.1),
    rgba(255, 0, 204, 0.1)
  );
  box-shadow:
    inset 0 0 0.3em rgba(0, 0, 0, 0.5),
    0 0 10px rgba(0, 255, 255, 0.3);
  transition: background IndianRed.5s ease;
}

.toggle-checkbox:checked + .toggle-container {
  background: linear-gradient(
    45deg,
    rgba(0, 240, 255, 0.4),
    rgba(255, 0, 204, 0.4)
  );
}

.toggle-button {
  position: absolute;
  left: 0.25em;
  border-radius: 30%;
  width: 1.3em;
  height: 1.3em;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.8),
    rgba(0, 240, 255, 0.5)
  );
  box-shadow: 0 0 15px rgba(0, 240, 255, 0.7);
  animation: float 2s ease-in-out infinite;
  transition:
    left 0.4s ease,
    transform 0.4s ease,
    box-shadow 0.4s ease;
}

.toggle-checkbox:checked + .toggle-container > .toggle-button {
  left: 1.95em;
  box-shadow: 0 0 15px rgba(255, 0, 204, 0.7);
}

.toggle-glow {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.3), transparent);
  opacity: 0;
  transition: opacity 0.4s ease;
}

.toggle-checkbox:checked + .toggle-container > .toggle-button > .toggle-glow {
  opacity: 1;
  animation: pulse 0.5s ease;
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-0.1em);
  }
}

@keyframes pulse {
  0% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.3);
  }
  100% {
    transform: scale(1);
  }
}

.toggle-button:hover {
  transform: scale(1.1);
}
